public <T> T retry(Supplier<T> operation, int maxRetries) {
	int attempts = 0;
	while (attempts < maxRetries) {
		try {
			return operation.get();
		} catch (Exception e) {
			attempts++;
			if (attempts >= maxRetries) throw e;
		}
	}
	throw new RuntimeException("Max retries exceeded");
}

